const cfg = $('Config da loja (Supabase)').first().json;
const catalogo = $('Catálogo disponível').all().map(i => i.json);
const cerebro = $('Prompt + conhecimento publicados').first().json;
const historico = $('Histórico (10-15 turnos)').all().map(i => i.json).reverse();
const body = $('Webhook Kommo').first().json.body;

const precoLiberado = cfg.price_source === 'manual' || cfg.price_integration_enabled;
const catalogoTexto = catalogo.map(i => `- ${i.model} ${i.storage} ${i.condition}${i.color ? ' ' + i.color : ''}${i.battery_health ? ' bateria ' + i.battery_health + '%' : ''} — R$ ${(i.price_cents/100).toFixed(2)} (estoque ${i.stock})`).join('\n') || 'SEM ITENS DISPONÍVEIS';

const system = [
  cerebro.prompt,
  '\n## Conhecimento\n' + cerebro.conhecimento,
  `\n## Loja\nNome: ${cfg.store_name}\nAgente: ${cfg.agent_name}\nRevelar que é virtual: ${cfg.reveal_virtual}\nSobre: ${cfg.about || '-'}`,
  `\n## Catálogo (única fonte de preço)\n${catalogoTexto}`,
  `\n## Regras\n- Nunca invente preço fora do catálogo.\n- Preço liberado nesta execução: ${precoLiberado}.\n- Responda SOMENTE com JSON: {"resposta","temperatura_lead","estagio","acao","motivo_handoff"}.`
].join('\n');

const mensagens = [...historico.map(m => ({ role: m.role === 'cliente' ? 'user' : 'assistant', content: m.content })), { role: 'user', content: body.message_text }];

return [{ json: { system, mensagens, cfg, body } }];

const TEMPS=['fria','morna','quente'];
const ESTAGIOS=['abertura','desenvolvimento','ancoragem','pre_fechamento','handoff'];
const ACOES=['conversar','passar_preco','encaminhar_humano'];
const MOTIVOS=['sinal_fechamento','troca','insistencia_preco','pedido_humano','fora_escopo'];
const FALLBACK={resposta:'Só um instante, vou chamar alguém do time para te ajudar melhor por aqui.',temperatura_lead:'morna',estagio:'handoff',acao:'encaminhar_humano',motivo_handoff:'fora_escopo'};
const raw=($input.first().json.content||[]).map(c=>c.text||'').join('\n');
let out=FALLBACK, ok=false;
try{ const s=raw.replace(/```(json)?/gi,'').replace(/`/g,''); const j=JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}')+1));
  const valido = typeof j.resposta==='string' && j.resposta.trim() && TEMPS.includes(j.temperatura_lead) && ESTAGIOS.includes(j.estagio) && ACOES.includes(j.acao) && (j.motivo_handoff===null||MOTIVOS.includes(j.motivo_handoff)) && !(j.acao==='encaminhar_humano' && !j.motivo_handoff);
  if(valido){ out=j; ok=true; }
}catch(e){}
return [{ json: { ...out, ok, raw } }];

// Aplica apenas as ações habilitadas na loja: parar bot, atribuir vendedor,
// mover etapa de Atendimento Humano e registrar nota (API Kommo).
const cfg = $('Montar system + mensagens').first().json.cfg;
return [{ json: { acoes: { parar_bot: cfg.handoff_stop_bot, atribuir: cfg.handoff_assign_user, mover_etapa: cfg.handoff_move_stage, nota: cfg.handoff_add_note }, cfg } }];
